import React from 'react'

function RandomPokemonRerollButton({ onReroll }) {
  return (
    <button
      onClick={onReroll}
      className='mt-4 px-4 py-2 bg-blue-light text-white rounded-lg hover:bg-blue-dark'
    >
      Reroll Pokémon
    </button>
  )
}

export default RandomPokemonRerollButton
